To design an end-user API for 3D camera animation in TypeScript, follow these steps:

1. Define the API structure:

Create an interface that defines the API's structure, including the endpoints and their parameters. For example:

```typescript
interface EndUserAPI {
  cameraAnimation: {
    start(options: StartCameraAnimationOptions): Promise<void>;
    stop(): Promise<void>;
    pause(): Promise<void>;
    resume(): Promise<void>;
    setPosition(position: Vector3): Promise<void>;
    setRotation(rotation: Quaternion): Promise<void>;
    setScale(scale: Vector3): Promise<void>;
  };
}
```

2. Create the API class:

Implement the API class using the `EndUserAPI` interface. This class will handle the communication with the server and provide a consistent interface for the end-user. For example:

```typescript
class EndUserAPIImpl implements EndUserAPI {
  private readonly baseUrl: string;
  private readonly apiKey: string;

  constructor(baseUrl: string, apiKey: string) {
    this.baseUrl = baseUrl;
    this.apiKey = apiKey;
  }

  async start(options: StartCameraAnimationOptions) {
    const url = `${this.baseUrl}/camera/animation`;
    const headers = {
      'Authorization': `Bearer ${this.apiKey}`,
      'Content-Type': 'application/json',
    };

    const requestBody = JSON.stringify(options);

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers,
        body: requestBody,
      });

      if (response.ok) {
        return await response.json();
      } else {
        throw new Error('Failed to start camera animation');
      }
    } catch (error) {
      console.error('Error starting camera animation:', error);
      throw error;
    }
  }

  // Implement other methods for stopping, pausing, resuming, setting position, rotation, and scale
}
```

