    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Strange Numbers Puzzle</title>
    <script>
        function solvePuzzle() {
            const table = document.getElementById('puzzle-table');
            const rows = table.querySelectorAll('tr');
            const missingRow = rows[rows.length - 1];
            const missingCell = missingRow.querySelector('td');

            const pairs = [];
            for (let i = 0; i < rows.length - 1; i++) {
                const row = rows[i];
                const cells = row.querySelectorAll('td');
                for (let j = 0; j < cells.length - 1; j++) {
                    const cell = cells[j];
                    const num = parseInt(cell.textContent);
                    const pair = [num / 10, num % 10];
                    pairs.push(pair);
                }
            }

            const missingPair = [missingCell.textContent / 10, missingCell.textContent % 10];
            const sum = missingPair[0] + missingPair[1];

            if (sum !== 9) {
                alert(`Incorrect pair. The missing pair should add up to 9.`);
                return;
            }

            const missingNumber = missingPair[0] * 10 + missingPair[1];
            missingCell.textContent = missingNumber;

            alert(`The missing number is ${missingNumber}.`);
        }
