    int purchasePrice = 1000;
    int residualValue = 200;
    int refundAmount = 600;

    int totalRefundAmount = refundAmount - residualValue;
    float percentageRefund = static_cast<float>(totalRefundAmount) / purchasePrice * 100;

    std::cout << "The percentage of refund is: " << percentageRefund << "%" << std::endl;

    return 0;
}
```
