To achieve this, you can use Google Apps Script along with the Google Maps API. Here's a simple script that searches for a place name in a column and stores the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A2:A"); // Assuming your data starts from cell A2
  var placeNames = dataRange.getValues().flat(); // Extract place names from the range

  var map = new google.maps.Map(document.getElementById('map'), {
    center: {lat: 37.7749, lng: -122.4194},
    zoom: 10
  });

  placeNames.forEach(function(placeName) {
    var geocoder = new google.maps.Geocoder();
    geocoder.geocode({address: placeName}, function(results, status) {
      if (status === 'OK') {
        var marker = new google.maps.Marker({
          position: results[0].geometry.location,
          map: map
        });

        var infoWindow = new google.maps.InfoWindow({
          content: placeName
        });

        marker.addListener('click', function() {
          infoWindow.open(map, marker);
        });

        // Store latitude and longitude in other columns
        sheet.getRange(sheet.getLastRow() + 1, 2).setValue(results[0].geometry.location.lat());
        sheet.getRange(sheet.getLastRow() + 1, 3).setValue(results[0].geometry.location.lng());
      } else {
        console.log('Geocode was not successful for the following reason: ', status);
      }
    });
  });
}
```

Replace `"A2:A"` with the actual range of cells containing place names. This script will search for each place name in the specified range, display markers on a map, and store the latitude and longitude in columns B and C, respectively.

