using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;

public class JwtTokenHandler
{
    private readonly TokenValidationParameters _validationParameters;

    public JwtTokenHandler(string secretKey)
    {
        _validationParameters = new TokenValidationParameters
        {
            IssuerSigningKey = secretKey,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero
        };
    }

    public string GetUsernameFromToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var securityToken = tokenHandler.ReadJwtToken(token, _validationParameters);
        var userIdentifierClaim = securityToken.Claims.FirstOrDefault(c => c.Type == "sub");
        return userIdentifierClaim?.Value;
    }
}
