```csharp
using UnityEngine;
using System.IO;
using UnityEngine.Audio;

public class MusicVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public Texture2D visualizerTexture;
    public float visualizerScale = 1f;

    private void Start()
    {
        if (audioSource == null)
        {
            audioSource = GetComponent<AudioSource>();
        }

        if (visualizerTexture == null)
        {
            visualizerTexture = Resources.Load<Texture2D>("Visualizer");
        }
    }

    private void Update()
    {
        float time = Time.time;
        float progress = audioSource.time / audioSource.clip.length;

        Vector2 visualizerPosition = new Vector2(progress * visualizerScale, 0f);
        Vector2 visualizerSize = new Vector2(visualizerScale, visualizerScale);

        Graphics.DrawTexture(visualizerPosition, visualizerSize, visualizerTexture);
    }
}
```
1. Attach the "MusicVisualizer" script to your game object.
2. Set the "AudioSource" component of the game object to the audio file you want to use.
3. Set the "VisualizerTexture" component of the game object to the visualizer asset you want to use.
4. Adjust the "VisualizerScale" component of the game object to control the size of the visualizer.
5. Run your game and you should see the visualizer displayed in time with the music.

Note: This script assumes that the visualizer texture is a square image. If the visualizer texture is not a square image, you may need to adjust the script to fit your specific needs.

